def eulerian_num(a, m):
    """
    Calculate Eulerian number a(n, m) for a given n and m.

    Parameters:
    a (int): The value of n.
    m (int): The value of m.

    Returns:
    int: The Eulerian number.
    """
    if a == 0:
        return 1
    else:
        return a + eulerian_num(a - 1, m) * eulerian_num(a - 1, m - 1)

def eulerian_num(n, m):
    # Base case: Eulerian number for 0 and 1 is 1
    if n == 0 or m == 0:
        return 1
    # Base case: Eulerian number for 1 and 2 is 1
    elif n == 1 and m == 2:
        return 1
    # Recursive case: Eulerian number is n * (eulerian_num(n-1, m-1) + eulerian_num(n-2, m))
    else:
        return n * (eulerian_num(n-1, m-1) + eulerian_num(n-2, m))

