            # If the current element is greater than the element before it, start a new sub-sequence
            if arr[j] > arr[i]:
                # Update the maximum sum ending at j by including the current element
                dp[i][j] = arr[j] + dp[i + 1][j - 1]
            else:
                # If the current element is less than or equal to the element before it, start a new sub-sequence
                dp[i][j] = arr[i]

    # The maximum sum is in the top-right cell of the dp table
    return dp[0][n - 1]

