            else:
                # Otherwise, the length is the maximum of the lengths of the subsequences up to the previous position
                t[i][j] = max(t[i-1][j], t[i][j-1])

    # The value in the bottom-right corner of the table gives the length of the longest palindromic subsequence
    return t[len(s)][len(s)]

