    # Initialize a 2D list to store the number of ways to make a sequence of length length with non-negative prefix sums
    dp = [[0 for i in range(length + 1)] for j in range(length + 1)]

    # Base case: There's one way to make a sequence of length 0 with no prefix sums
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, length + 1):
        for j in range(1, length + 1):
            if j >= i:
                # If the prefix sum can be formed with the remaining prefix sums
                dp[i][j] = dp[i - 1][j] + dp[i - 1][j - i]
            else:
                # If the prefix sum cannot be formed, there are no ways to make the sequence
                dp[i][j] = 0

    # The answer is the number of ways to make a sequence of length length with non-negative prefix sums
    return dp[length][length]

