def swap_count(s):
    # Count the number of unmatched opening brackets
    open_brackets = 0
    # Initialize the count of unmatched closing brackets
    close_brackets = 0
    # Iterate through each character in the string
    for char in s:
        # If it's an opening bracket, increment the open_brackets counter
        if char == '[':
            open_brackets += 1
        # If it's a closing bracket, decrement the close_brackets counter
        elif char == ']':
            close_brackets += 1
        # If there are more closing brackets than opening ones, swap them
        if close_brackets > open_brackets:
            # Swap the unmatched opening and closing brackets
            open_brackets, close_brackets = close_brackets, open_brackets
    # The minimum swaps required is the minimum of open_brackets and close_brackets
    return min(open_brackets, close_brackets)

