    # Check if all three numbers are equal
    if x == y == z:
        return x
    # Sort the numbers
    sorted_numbers = sorted([x, y, z])
    # Return the middle element if there are an odd number of elements
    if len(sorted_numbers) % 2 == 1:
        return sorted_numbers[len(sorted_numbers) // 2]
    # Return the average of the two middle elements if there are an even number of elements
    else:
        return (sorted_numbers[len(sorted_numbers) // 2 - 1] + sorted_numbers[len(sorted_numbers) // 2]) / 2

