def ncr_modp(n, r, p):
    # Calculate nCr % p using the formula nCr = (n * (n-1) * ... * (n-r+1)) % p
    return (n * (n-1) * ... * (n-r+1)) % p

def ncr_modp(n, r, p):
    # Base case: if n is 0 or r is 0, return 0
    if n == 0 or r == 0:
        return 0
    # Initialize variables for memoization
    memo = [[0] * (r + 1) for _ in range(n + 1)]
    # Fill the memoization table
    for i in range(n + 1):
        for j in range(r + 1):
            if i < j:
                memo[i][j] = 0
            elif i == j:
                memo[i][j] = 1
            else:
                memo[i][j] = (memo[i - 1][j] + memo[i][j - 1]) % p
    # Return the value at the bottom-right corner of the memoization table
    return memo[n][r]

