def rearrange_bigger(n):
    # Convert the number to a string to easily manipulate the digits
    str_n = str(n)
    # Find the last occurrence of the digit that is smaller than its next digit
    for i in range(len(str_n) - 1, 0, -1):
        if str_n[i] < str_n[i + 1]:
            # Extract the digit and move it to the end of the string
            str_n = str_n[:i] + str_n[i + 1:] + str_n[i]
            # Convert the string back to an integer
            return int(str_n)
    # If no such digit exists, return the largest possible number
    return int('9' * len(str_n))

